import sys,itertools,functools
edges=[560,630,690,750,820]
PD=np.array([.02,.05,.12,.3,.6,.9]);AV=(1-PD)*1000-PD*16000
P={}
for c in 'bik':
  res=np.concatenate([np.array(D[(s,c)])-np.median(D[(s,c)]) for s in range(1,7)])
  for s in range(1,7):
    m=np.median(D[(s,c)]);x=m+res
    b=np.searchsorted(edges,x,side='right')
    p=np.bincount(b,minlength=6)/len(x)+0.004
    P[(s-1,c)]=p/p.sum()
def post(prior,hist):
  p=np.array(prior,float)
  for c,b in hist:p=p*np.array([P[(s,c)][b] for s in range(6)])
  return p/p.sum()
def val(p,depth):
  ap=float(p@AV);best=max(ap,0)
  if depth==0:return best,None
  bc=None
  for c in 'bik':
    v=-20
    for b in range(6):
      pb=sum(p[s]*P[(s,c)][b] for s in range(6))
      v+=pb*val(p*np.array([P[(s,c)][b] for s in range(6)])/pb,depth-1)[0]
    if v>best+1e-9:best=v;bc=c
  return best,bc
if __name__=='__main__':
  prior=[float(x) for x in sys.argv[1].split(',')]
  hist=[(h[0],int(h[1])) for h in sys.argv[2:]]
  p=post(prior,hist)
  print(np.round(p,3),'approveEV',round(float(p@AV)))
  print(val(p,2) if len(hist)<7 else val(p,0))
